// ============================================================
// SCORE CALCULATOR — النسخة النهائية
// Greeting + Punctuation = 5 دايماً بغض النظر عن التقييم
// ============================================================

let raw = $json.output;
let ai = {};

if (typeof raw === 'string') {
  try {
    const cleaned = raw.replace(/```json|```/gi, '').trim();
    ai = JSON.parse(cleaned);
  } catch { ai = {}; }
} else if (typeof raw === 'object' && raw !== null) {
  ai = raw;
}

const required = ['greeting', 'misspellings', 'punctuation', 'slang', 'thanks'];
const missing = required.filter(f => !ai[f]);
if (missing.length > 2) {
  return [{
    json: {
      output: {
        error: true,
        error_reason: 'AI response incomplete',
        missing_fields: missing,
        raw_output: raw,
      }
    }
  }];
}

const val = (v) => v ? v.toString().toLowerCase().trim() : '';

const scores = {
  greeting:     { full: 5, partial: 5, none: 5 },  // دايماً 5
  misspellings: { good: 10, bad: 0 },
  punctuation:  { good: 5, bad: 5 },               // دايماً 5
  slang:        { none: 5, minor: 3, exists: 0 },
  thanks:       { yes: 5, no: 0 },
};

const getScore = (map, key) => {
  if (!key || !map) return 0;
  if (map[key] !== undefined) return map[key];
  return 0;
};

const greeting_score     = getScore(scores.greeting,     val(ai.greeting));
const misspellings_score = getScore(scores.misspellings, val(ai.misspellings));
const punctuation_score  = getScore(scores.punctuation,  val(ai.punctuation));
const slang_score        = getScore(scores.slang,        val(ai.slang));
const thanks_score       = getScore(scores.thanks,       val(ai.thanks));

const total = greeting_score + misspellings_score + punctuation_score + slang_score + thanks_score;
const MAX = 30;
const percentage = Math.round((total / MAX) * 100);

let performance = 'Poor';
if (percentage >= 85) performance = 'Excellent';
else if (percentage >= 70) performance = 'Good';
else if (percentage >= 50) performance = 'Average';

const ticket = $node["Code in JavaScript"].json;

return [{
  json: {
    output: {
      current_date: new Date().toISOString(),
      ticket_number: ticket.id ?? 'N/A',
      ticket_created_at: ticket.created_at ?? 'N/A',
      employee_name: ticket.assigned_user || 'Unknown',
      employee_id: ticket.assigned_user_id || 'N/A',
      is_transferred: ticket.is_transferred || false,
      is_bot_greeting: ticket.is_bot_greeting || false,

      total_score: total,
      max_score: MAX,
      percentage: percentage,
      performance: performance,

      breakdown: {
        Complete_Greeting: {
          score: greeting_score,
          max: 5,
          label: ai.greeting,
          reason: ai.greeting_reason || '',
          note: 'الدرجة ثابتة 5 بغض النظر عن التقييم',
        },
        Misspellings: {
          score: misspellings_score,
          max: 10,
          label: ai.misspellings,
          reason: ai.misspellings_reason || '',
          note: misspellings_score === 0 ? 'خُصم 10 نقاط بسبب أخطاء إملائية واضحة' : '',
        },
        Punctuation: {
          score: punctuation_score,
          max: 5,
          label: ai.punctuation,
          reason: ai.punctuation_reason || '',
          note: 'الدرجة ثابتة 5 بغض النظر عن التقييم',
        },
        Slang_Words: {
          score: slang_score,
          max: 5,
          label: ai.slang,
          reason: ai.slang_reason || '',
        },
        Thanks_Customer: {
          score: thanks_score,
          max: 5,
          label: ai.thanks,
          reason: ai.thanks_reason || '',
        },
      }
    }
  }
}];

// ============================================================
// CODE NODE v10 — النسخة النهائية المضمونة
// بيستخدم user.is_client لتمييز العميل والموظف بدقة 100%
// مكانه: بعد Edit Fields مباشرة
// ============================================================

const rawMessages = $json.messages;
const messages = typeof rawMessages === 'string'
  ? JSON.parse(rawMessages)
  : (rawMessages || []);

// ============================================================
// تمييز الرسايل باستخدام is_client
// ============================================================
const taggedMessages = messages
  .filter(m => m.content !== null || m.file !== null)
  .map(m => {
    const user = m.user || {};
    const isClient = user.is_client === true;
    const isAI = (user.name || '').toLowerCase().includes('ai') ||
                 (user.name || '').toLowerCase().includes('customer service') ||
                 (user.first_name || '').toLowerCase() === 'ai';

    m._isAgent = !isClient;
    m._isAI = isAI;
    m._isInternalNote = false;
    return m;
  });

// ============================================================
// كشف البوت — لو أول رسالة AGENT جت في أقل من 120 ثانية
// أو لو المرسل اسمه AI
// ============================================================
const firstCustomerMsg = taggedMessages.find(m => !m._isAgent);
const firstAgentMsg = taggedMessages.find(m => m._isAgent && !m._isAI);

let is_bot_greeting = false;

if (firstCustomerMsg && firstAgentMsg) {
  const customerTime = new Date(firstCustomerMsg.created_at);
  const agentTime = new Date(firstAgentMsg.created_at);
  const diffSeconds = (agentTime - customerTime) / 1000;
  if (diffSeconds < 120) is_bot_greeting = true;
}

// لو أول رسالة AGENT هي AI → bot greeting
const firstMsg = taggedMessages.find(m => m._isAgent);
if (firstMsg && firstMsg._isAI) is_bot_greeting = true;

// ============================================================
// كشف التذكرة المحولة
// ============================================================
let isTransferredByDate = false;
const createdAt = $json.created_at;
const assignDate = $json.assign_date;

if (createdAt && assignDate) {
  const diffMinutes = Math.abs(new Date(assignDate) - new Date(createdAt)) / 60000;
  if (diffMinutes > 5) isTransferredByDate = true;
}

const transferKeywords = [
  'هحول التذكرة', 'بحول التذكرة',
  'هيتم تحويل', 'سيتم تحويل',
  'هحولها', 'بحولها', 'تم تحويل',
];

const firstRealAgentMsg = taggedMessages.find(m => m._isAgent && !m._isAI);
const isTransferredByKeyword = firstRealAgentMsg
  ? transferKeywords.some(k => (firstRealAgentMsg.content || '').includes(k))
  : false;

const is_transferred = isTransferredByDate || isTransferredByKeyword;

// ============================================================
// بناء الـ conversation
// بنشيل رسايل الـ AI من الـ conversation
// عشان الـ AI يقيم الموظف البشري بس
// ============================================================
const conversation = taggedMessages
  .filter(m => !m._isAI)
  .map(m => {
    const role = m._isAgent ? '[AGENT]' : '[CUSTOMER]';
    const time = m.created_at ? `(${m.created_at})` : '';
    const content = m.content || '';
    const file = m.file ? '[FILE/SCREENSHOT]' : '';
    return `${role} ${time}: ${content} ${file}`.trim();
  })
  .join('\n');

// ============================================================
// OUTPUT
// ============================================================
return [{
  json: {
    id: $json.id,
    creator_id: $json.creator_id,
    creator_name: $json.creator_name,
    assigned_user: $json.assigned_user,
    assigned_user_id: $json.assigned_user_id,
    created_at: $json.created_at,
    updated_at: $json.updated_at,
    assign_date: $json.assign_date,
    close_date: $json.close_date,
    complaint_type: $json.complaint_type,
    complaint_type_title: $json.complaint_type_title,
    main_question: $json.main_question,
    user_rate: $json.user_rate,
    is_transferred,
    is_bot_greeting,
    conversation,
  }
}];

// ============================================================
// CLASSIFICATION PARSER — normalizes the Ticket Classification Agent output
// وبيجيب معاه التصنيف الأساسي (الأصلي) من نظام الشركة عشان المقارنة
// ============================================================

let raw = $json.output;
let ai = {};

if (typeof raw === 'string') {
  try {
    const cleaned = raw.replace(/```json|```/gi, '').trim();
    ai = JSON.parse(cleaned);
  } catch {
    ai = {};
  }
} else if (typeof raw === 'object' && raw !== null) {
  ai = raw;
}

// الفئات الرئيسية المسموح بيها
const allowedMain = ['شكوى', 'استفسار', 'شكر', 'مقترح'];

// الفئات الفرعية المسموح بيها لكل فئة رئيسية (نفس ليستة الشركة بالظبط)
const allowedTitles = {
  'شكوى': [
    'أخرى', 'إفادة وهمية', 'المهمة غير قابلة للإنشاء', 'الموظف المسؤول عن الفرع',
    'تاخير الاستلام', 'تأخير التسليم', 'تأخير تحويل التوريد', 'تبديل في التسليم',
    'تلف الطرد', 'جزء من الطرد مفقود', 'حجم المركبة/المعدة غير مناسب',
    'خارج التغطية', 'خطأ في الحسابات المالية', 'خطأ في تفاصيل المهمة',
    'طرد مفقود', 'عدم الاستجابة من الفرع', 'عدم الاستلام', 'كابتن الاستلام',
    'مرتجع على الراسل غير مستحق', 'مشكلة مع الكابتن'
  ],
  'استفسار': ['أخرى', 'بخصوص التشغيل', 'سيستم التطبيق', 'سيستم الويب'],
  'شكر': ['شكر'],
  'مقترح': ['مقترح']
};

// STEP 1: تحقق من الفئة الرئيسية
let classification = (ai.ticket_classification || '').toString().trim();
if (!allowedMain.includes(classification)) {
  classification = classification || 'غير محدد';
}

// STEP 2: تحقق من الفئة الفرعية (لازم تكون تابعة للفئة الرئيسية اللي اتحددت)
let classificationTitle = (ai.classification_title || '').toString().trim();
const validTitlesForMain = allowedTitles[classification] || [];
if (!validTitlesForMain.includes(classificationTitle)) {
  classificationTitle = classificationTitle || 'غير محدد';
}

// نجيب بيانات المصدر الأصلي (نفس الفرع، الـ node ده أب لل Ticket Classification Agent)
const source = $('Code in JavaScript').item.json;

// نجيب الـ ticket_id من رد الـ AI، ولو مش موجود نرجع للمصدر الأساسي
const ticketIdFromAI = (ai.ticket_id || '').toString().trim();
const ticket_id = ticketIdFromAI || source.id;

return [{
  json: {
    classification: {
      ticket_id: ticket_id,
      original_type: source.complaint_type || 'N/A',
      original_type_title: source.complaint_type_title || 'N/A',
      ticket_classification: classification,
      ai_classification_title: classificationTitle,
      classification_reason: ai.classification_reason || ''
    }
  }
}];
